found = {}   # phone-normalized -> guid
CH = 14
for i in range(0, len(VARIANTS), CH):
    chunk = VARIANTS[i:i+CH]
    req = urllib.request.Request(URL,
        data=json.dumps({"objectType": 1,
            "fields": [{"name":"telephone1"},{"name":"telephone2"}],
            "pageSize": 500, "pageNumber": 1,
            "filter": [{"type":"or","conditions":[
                {"fieldName":"telephone1","operator":"eq-in","value":chunk},
                {"fieldName":"telephone2","operator":"eq-in","value":chunk}]}]}).encode(), headers=HDRS)
    for attempt in range(3):
        try:
            r = urllib.request.urlopen(req, timeout=60)
            d = json.loads(r.read()); break
        except Exception as e:
            if attempt == 2:
                print("chunk", i, "FAIL", str(e)[:100], flush=True)
                d = {"data": []}; break
            time.sleep(2)
    rows = d.get("data", [])
    for x in rows:
        guid = x.get("_id")
        for f in ("telephone1", "telephone2"):
            v = x.get(f)
            if v:
                v = str(v).strip().replace("-", "")
                if v.startswith("+972"): v = "0" + v[4:]
                elif v.startswith("972") and len(v) == 12: v = "0" + v[3:]
                found[v] = guid
    print(f"chunk {i//CH}: +{len(rows)} (unique phones {len(found)})", flush=True)
    time.sleep(0.5)

